        data-testid="project-tag-filter"
        value={selected ?? ''}
        onChange={(event) => setSelected(event.target.value ? Number(event.target.value) : undefined)}
      >
        <option value="">All labels</option>
        {(tags ?? []).map((tag: TagOption) => (
          <option key={tag.id} value={tag.id}>
            {tag.name}
          </option>
        ))}
      </select>
    </label>
  );
}

