import {
  clientProjectsKey,
  fetchClientProjects,
  isActiveProject,
  CLIENT_PROJECTS_SHOW_ALL_PARAM,
  type ClientProject,
} from './queries';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// The projects the user is doing for one client. Queries for itself under ['clients', clientId,
