}

import { useQuery } from '@tanstack/react-query';
import { ClientDetail } from '../../slots/defs/clientDetail';
import { clientProjectsKey, fetchClientProjects } from './queries';
import { clientContactsKey, fetchClientContacts } from '../contacts/queries';

// At-a-glance counts of a client's projects and contacts — one new *.slot.tsx filling the
// ClientDetail region (CLAUDE.md rule 3). Nothing existing is edited. It reads the SAME nested keys
// the projects/contacts tables use (rule 5), so a write elsewhere that invalidates ['clients']
// refreshes these numbers too, with no import between features.
function ClientCounts({ clientId }: { clientId: number }) {
  const { data: projects } = useQuery({
    queryKey: clientProjectsKey(clientId),
    queryFn: () => fetchClientProjects(clientId),
  });
  const { data: contacts } = useQuery({
    queryKey: clientContactsKey(clientId),
    queryFn: () => fetchClientContacts(clientId),
  });

  return (
    <dl data-testid="client-counts">
      <div>
        <dt>Projects</dt>
        <dd data-testid="client-projects-count">{projects?.length ?? 0}</dd>
      </div>
      <div>
        <dt>Contacts</dt>
        <dd data-testid="client-contacts-count">{contacts?.length ?? 0}</dd>
      </div>
    </dl>
  );
}

export const contribution = ClientDetail.fill({ order: 5, Component: ClientCounts });

import { ClientDetail } from '../../slots/defs/clientDetail';
import { useSearchParam, asFlag } from '../../url/useSearchParam';
import { CLIENT_PROJECTS_SHOW_ALL_PARAM } from './queries';

// The "show all projects" toggle on a client's detail page — one new *.slot.tsx file filling the
// ClientDetail region (CLAUDE.md rule 3). Nothing existing is edited to add it. It owns the
// `clientProjectsAll` URL key (rule 4): whether the finished and hidden projects are revealed
// outlives a click, so it lives in the URL, and the projects table reads the same key to decide
// which rows show. No callback, no shared state — just the key.
function ShowAllProjectsToggle() {
  const [showAll, setShowAll] = useSearchParam(CLIENT_PROJECTS_SHOW_ALL_PARAM, asFlag);
  return (
    <label>
      <input
        type="checkbox"
        data-testid="client-projects-show-all"
        checked={showAll}
        onChange={(event) => setShowAll(event.target.checked ? true : undefined)}
      />
      Show finished and hidden projects
    </label>
  );
}

export const contribution = ClientDetail.fill({ order: 10, Component: ShowAllProjectsToggle });
